{"implementation":"def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError('Missing required fields')
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('Segment missing required fields')
        if not isinstance(s['minimum'], int) or not isinstance(s['capacity'], int) or not isinstance(s['importance'], int):
            raise ValueError('Segment fields must be integers')
    n = len(segments)
    allocations = [s['minimum'] for s in segments]
    total_min = sum(allocations)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of feasible range')
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_num = 0
        best_den = 1
        for i in range(n):
            if allocations[i] >= segments[i]['capacity']:
                continue
            num = segments[i]['importance']
            den = allocations[i] + 1
            if best_idx == -1 or num * best_den > best_num * den:
                best_idx = i
                best_num = num
                best_den = den
            elif num * best_den == best_num * den and i < best_idx:
                best_idx = i
                best_num = num
                best_den = den
        if best_idx == -1:
            raise ValueError('Could not allocate budget')
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"}
